import sys
P = 'design/registry/entities.yaml'


class Ed:
    def __init__(self):
        self.s = open(P, encoding='utf-8').read()
        self.log = []

    def rep(self, old, new, tag):
        n = self.s.count(old)
        assert n == 1, (tag, n)
        self.s = self.s.replace(old, new)
        self.log.append(tag)

    def ins_before(self, anchor, text, tag):
        self.rep(anchor, text + anchor, tag)

    def save(self):
        open(P, 'w', encoding='utf-8').write(self.s)
        print(len(self.log), 'edits:', ', '.join(self.log))

